    ms=[summ('Recognized Revenue','Performance','RecognizedRevenue','Accrual revenue recognized for the reporting period.'),summ('Labor Cost','Performance','LaborCost'),summ('Subcontract Cost','Performance','SubcontractCost'),summ('Expenses','Performance','Expenses'),measure('Delivery Cost','[Labor Cost] + [Subcontract Cost] + [Expenses]','Direct project delivery cost excluding general overhead.',MONEY),measure('Project Profit','[Recognized Revenue] - [Delivery Cost]','Recognized revenue less direct delivery cost.',MONEY),measure('Project Margin','DIVIDE([Project Profit], [Recognized Revenue])','Project profit / recognized revenue.',PCT),summ('Cost Budget','Performance','CostBudget','Monthly allocated direct delivery budget.'),measure('Budget Remaining','[Cost Budget] - [Delivery Cost]','Allocated budget less actual cost; positive is under budget.',MONEY),summ('Actual Hours','Performance','ActualHours',fmt='#,0'),summ('Planned Hours','Performance','PlannedHours',fmt='#,0'),measure('Hours Variance','[Actual Hours] - [Planned Hours]','Positive means more hours consumed than planned.'),measure('Effective Revenue per Hour','DIVIDE([Recognized Revenue], [Actual Hours])','Recognized revenue per actual delivery hour.',MONEY),summ('Invoiced','Performance','Invoiced'),summ('Collected','Performance','Collected'),measure('Invoice Cash Gap','[Invoiced] - [Collected]','Selected-period invoices minus collections. Not accounts-receivable balance or overdue debt.',MONEY)]
    sl=['Calendar.Month','Projects.Manager','Projects.Service']
