    return base('09-project-profitability','Project Profitability Dashboard','Project intelligence','Find unprofitable engagements, budget overruns and differences between project revenue, invoices and receipts.','Jan–Sep 2026 monthly project performance.','One row per project/month. Recognized revenue is independent of invoices and cash. CostBudget is allocated monthly, not a repeated full-project budget. Collections can exceed current invoices with opening receivables in real data. Invoice cash gap is not an overdue balance; opening receivables and due dates are outside scope.',{'Projects':table(projs,'ProjectID','one project'),'Performance':table(rows,'PeriodID','one project per month',dates=['Date'],decimals=['RecognizedRevenue','LaborCost','SubcontractCost','Expenses','CostBudget','Invoiced','Collected'])},[('Performance','ProjectID','Projects','ProjectID'),('Performance','Date','Calendar','Date')],ms,ps,{'Recognized Revenue':rev,'Delivery Cost':cost,'Project Profit':rev-cost,'Project Margin':ratio(rev-cost,rev),'Budget Remaining':total(rows,'CostBudget')-cost,'Invoice Cash Gap':round(total(rows,'Invoiced')-total(rows,'Collected'),2)})

