    sl=['Calendar.Month','Teams.Location','Jobs.Service']
    ps=[page('Management scorecard',sl,['Jobs Created','Open Jobs','On Time Rate','First Pass Yield'],'Teams.Team',['Completed Jobs','Open Jobs'],'Calendar.Month',['On Time Rate'],['Teams.Team','Jobs Created','Completed Jobs','On Time Rate','Rework Rate'],kind2='lineChart'),page('Backlog and service',sl,['Open Jobs','Overdue Open Jobs','Average Cycle Days','Completion Rate'],'Jobs.Priority',['Open Jobs','Overdue Open Jobs'],'Teams.Team',['Overdue Open Jobs'],['Jobs.JobID','Teams.Team','Jobs.Priority','Jobs.DueDate','Open Jobs','Overdue Open Jobs']),page('Quality and cost',sl,['Rework Jobs','Rework Rate','Recorded Cost','Cost per Completed Job'],'Jobs.Service',['First Pass Yield'],'Calendar.Month',['Recorded Cost'],['Teams.Team','Completed Jobs','Average Cycle Days','First Pass Yield','Cost per Completed Job'],kind2='lineChart')]
    return base('10-operations-kpis','Operations & Management KPI Dashboard','Operations intelligence','Track current backlog, on-time completion, service cycle time, rework and delivery cost.','Creation-date cohorts and current job status at 30 Sep 2026.','Month means CreatedDate. CompletedDate is required for Completed and blank for Open. OnTime and Rework are 0/1 and zero for open jobs. CompletedDate >= CreatedDate; CycleDays must match. DueDate is a calendar-date SLA, not business-hour SLA. Update as-of DATE in overdue measure when using a newer snapshot. Historical backlog and completion-date throughput need a separate event history.',{'Teams':table(teams,'TeamID','one operations team'),'Jobs':table(rows,'JobID','one current job snapshot',dates=['CreatedDate','DueDate','CompletedDate'],decimals=['Cost'])},[('Jobs','TeamID','Teams','TeamID'),('Jobs','CreatedDate','Calendar','Date')],ms,ps,{'Jobs Created':len(rows),'Completed Jobs':len(done),'Open Jobs':len(opened),'On Time Rate':ratio(total(done,'OnTime'),len(done)),'Overdue Open Jobs':len(late),'First Pass Yield':ratio(len(done)-total(done,'Rework'),len(done)),'Recorded Cost':total(rows,'Cost')})

